public class Example {
    void processText(String input, boolean skipLeadingWhitespace) {
        String text = input;
        if (skipLeadingWhitespace) {
            text = text.replaceFirst("^\\s+", "");
        }
        System.out.println(text);
    }
    void otherMethod(String someText) {
        String result = someText.replaceFirst("prefix", ""); // Should not match
        System.out.println(result);
    }
}

afterExample:
public class Example {
    void processText(String input, boolean skipLeadingWhitespace) {
        String text = input;
        if (skipLeadingWhitespace) {
            text = text.replaceFirst("^\\s+", "");
            text = text.replaceAll("(\\r\\n?|\\n)([ \\t]*\\*)", "$1");
        }
        System.out.println(text);
    }
    void otherMethod(String someText) {
        String result = someText.replaceFirst("prefix", ""); // Should not match
        System.out.println(result);
    }
}

